size_t RegisterJPEGImage(void) {
  MagickInfo *magick_info;
  size_t length = 0;

  const char *version = "JPEG";
  const char *description = "JPEG (Joint Photographic Experts Group)";
  const char *mime_type = "image/jpeg";

  magick_info = (MagickInfo *) AcquireMagickMemory(sizeof(*magick_info));
  if (magick_info == (MagickInfo *) NULL)
    return 0;

  (void) ConstantString(magick_info->version, version);
  (void) ConstantString(magick_info->description, description);

  magick_info->decoder = JPEGImage;
  magick_info->encoder = WriteJPEGImage;
  magick_info->thread_support = MagickTrue;

  if (JPEG_SUPPORT_THREADS)
    magick_info->thread_support = MagickTrue;
  else
    magick_info->thread_support = MagickFalse;

  (void) ConstantString(magick_info->mime_type, mime_type);
  magick_info->seekable = MagickTrue;

  magick_info = RegisterMagickInfo("JPE", magick_info);
  if (magick_info == (MagickInfo *) NULL)
    return 0;

  magick_info = RegisterMagickInfo("JPEG", magick_info);
  if (magick_info == (MagickInfo *) NULL)
    return 0;

  magick_info = RegisterMagickInfo("JPG", magick_info);
  if (magick_info == (MagickInfo *) NULL)
    return 0;

  magick_info = RegisterMagickInfo("JPS", magick_info);
  if (magick_info == (MagickInfo *) NULL)
    return 0;

  magick_info = RegisterMagickInfo("PJPEG", magick_info);
  if (magick_info == (MagickInfo *) NULL)
    return 0;

  length = sizeof(*magick_info);

  return length;
}

